    public IEnumerable<string>? PlacementStrategy { get; set; }

    /// <summary>
    /// The platform version that your tasks in the service run on. A plat- form version is only specified for tasks using the Fargate launch type. If a platform version is not specified, the LATEST platform version is used. For more information, see Fargate Platform Versions in the Amazon Elastic Container Service Developer Guide . This parameter triggers a new service deployment.
    /// </summary>
    [CliOption("--platform-version")]
    public string? PlatformVersion { get; set; }

    /// <summary>
    /// Determines whether to force a new deployment of the service. By de- fault, deployments aren't forced. You can use this option to start a new deployment with no service definition changes. For example, you can update a service's tasks to use a newer Docker image with the same image/tag combination (my_image:latest ) or to roll Fargate tasks onto a newer platform version.
    /// </summary>
    [CliFlag("--force-new-deployment", NegatedName = "--no-force-new-deployment")]
    public bool? ForceNewDeployment { get; set; }

    /// <summary>
    /// The period of time, in seconds, that the Amazon ECS service sched- uler ignores unhealthy Elastic Load Balancing, VPC Lattice, and con- tainer health checks after a task has first started. If you don't specify a health check grace period value, the default value of 0 is used. If you don't use any of the health checks, then healthCheck- GracePeriodSeconds is unused. If your service's tasks take a while to start and respond to health checks, you can specify a health check grace period of up to 2,147,483,647 seconds (about 69 years). During that time, the Amazon ECS service scheduler ignores health check status. This grace period can prevent the service scheduler from marking tasks as unhealthy and stopping them before they have time to come up. If your service has more running tasks than desired, unhealthy tasks in the grace period might be stopped to reach the desired count. This parameter doesn't trigger a new service deployment.
    /// </summary>
    [CliOption("--health-check-grace-period-seconds")]
    public int? HealthCheckGracePeriodSeconds { get; set; }

    /// <summary>
    /// The deployment controller to use for the service. type -&gt; (string) [required] The deployment controller type to use. The deployment controller is the mechanism that determines how tasks are deployed for your service. The valid options are: o ECS When you create a service which uses the ECS deployment controller, you can choose between the following deployment strategies: o ROLLING : When you create a service which uses the rolling update (ROLLING ) deployment strategy, the Amazon ECS ser- vice scheduler replaces the currently running tasks with new tasks. The number of tasks that Amazon ECS adds or removes from the service during a rolling update is controlled by the service deployment configuration. Rolling update de- ployments are best suited for the following scenarios: o Gradual service updates: You need to update your service incrementally without taking the entire service offline at once. o Limited resource requirements: You want to avoid the addi- tional resource costs of running two complete environments simultaneously (as required by blue/green deployments). o Acceptable deployment time: Your application can tolerate a longer deployment process, as rolling updates replace tasks one by one. o No need for instant roll back: Your service can tolerate a rollback process that takes minutes rather than seconds. o Simple deployment process: You prefer a straightforward deployment approach without the complexity of managing multiple environments, target groups, and listeners. o No load balancer requirement: Your service doesn't use or require a load balancer, Application Load Balancer, Net- work Load Balancer, or Service Connect (which are required for blue/green deployments). o Stateful applications: Your application maintains state that makes it difficult to run two parallel environments. o Cost sensitivity: You want to minimize deployment costs by not running duplicate environments during deployment. Rolling updates are the default deployment strategy for ser- vices and provide a balance between deployment safety and re- source efficiency for many common application scenarios. o BLUE_GREEN : A blue/green deployment strategy (BLUE_GREEN ) is a release methodology that reduces downtime and risk by running two identical production environments called blue and green. With Amazon ECS blue/green deployments, you can validate new service revisions before directing production traffic to them. This approach provides a safer way to de- ploy changes with the ability to quickly roll back if needed. Amazon ECS blue/green deployments are best suited for the following scenarios: o Service validation: When you need to validate new service revisions before directing production traffic to them o Zero downtime: When your service requires zero-downtime deployments o Instant roll back: When you need the ability to quickly roll back if issues are detected o Load balancer requirement: When your service uses Applica- tion Load Balancer, Network Load Balancer, or Service Con- nect o External Use a third-party deployment controller. o Blue/green deployment (powered by CodeDeploy) CodeDeploy in- stalls an updated version of the application as a new replace- ment task set and reroutes production traffic from the origi- nal application task set to the replacement task set. The original task set is terminated after a successful deployment. Use this deployment controller to verify a new deployment of a service before sending production traffic to it. Possible values: o ECS o CODE_DEPLOY o EXTERNAL Shorthand Syntax: type=string JSON Syntax: { "type": "ECS"|"CODE_DEPLOY"|"EXTERNAL" }
    /// </summary>
    [CliOption("--deployment-controller")]
    public string? DeploymentController { get; set; }

    /// <summary>
    /// If true , this enables execute command functionality on all task containers. If you do not want to override the value that was set when the ser- vice was created, you can set this to null when performing this ac- tion. This parameter doesn't trigger a new service deployment.
    /// </summary>
    [CliFlag("--enable-execute-command")]
    public bool? EnableExecuteCommand { get; set; }

    /// <summary>
    /// Determines whether to turn on Amazon ECS managed tags for the tasks in the service. For more information, see Tagging Your Amazon ECS Resources in the Amazon Elastic Container Service Developer Guide . Only tasks launched after the update will reflect the update. To up- date the tags on all tasks, set forceNewDeployment to true , so that Amazon ECS starts new tasks with the updated tags. This parameter doesn't trigger a new service deployment.
    /// </summary>
    [CliFlag("--enable-ecs-managed-tags", NegatedName = "--no-enable-ecs-managed-tags")]
    public bool? EnableEcsManagedTags { get; set; }

    /// <summary>
    /// NOTE: You must have a service-linked role when you update this prop- erty A list of Elastic Load Balancing load balancer objects. It contains the load balancer name, the container name, and the container port to access from the load balancer. The container name is as it ap- pears in a container definition. When you add, update, or remove a load balancer configuration, Ama- zon ECS starts new tasks with the updated Elastic Load Balancing configuration, and then stops the old tasks when the new tasks are running. For services that use rolling updates, you can add, update, or re- move Elastic Load Balancing target groups. You can update from a single target group to multiple target groups and from multiple tar- get groups to a single target group. For services that use blue/green deployments, you can update Elastic Load Balancing target groups by using `` CreateDeployment `` through CodeDeploy. Note that multiple target groups are not supported for blue/green deployments. For more information see Register multiple target groups with a service in the Amazon Elastic Container Service Developer Guide . For services that use the external deployment controller, you can add, update, or remove load balancers by using CreateTaskSet . Note that multiple target groups are not supported for external deploy- ments. For more information see Register multiple target groups with a service in the Amazon Elastic Container Service Developer Guide . You can remove existing loadBalancers by passing an empty list. This parameter triggers a new service deployment. (structure) The load balancer configuration to use with a service or task set. When you add, update, or remove a load balancer configuration, Amazon ECS starts a new deployment with the updated Elastic Load Balancing configuration. This causes tasks to register to and deregister from load balancers. We recommend that you verify this on a test environment before you update the Elastic Load Balancing configuration. A service-linked role is required for services that use multiple target groups. For more information, see Using service-linked roles in the Amazon Elastic Container Service Developer Guide . targetGroupArn -&gt; (string) The full Amazon Resource Name (ARN) of the Elastic Load Bal- ancing target group or groups associated with a service or task set. A target group ARN is only specified when using an Applica- tion Load Balancer or Network Load Balancer. For services using the ECS deployment controller, you can specify one or multiple target groups. For more information, see Registering multiple target groups with a service in the Amazon Elastic Container Service Developer Guide . For services using the CODE_DEPLOY deployment controller, you're required to define two target groups for the load bal- ancer. For more information, see Blue/green deployment with CodeDeploy in the Amazon Elastic Container Service Developer Guide . WARNING: If your service's task definition uses the awsvpc network mode, you must choose ip as the target type, not instance . Do this when creating your target groups because tasks that use the awsvpc network mode are associated with an elastic network interface, not an Amazon EC2 instance. This network mode is required for the Fargate launch type. loadBalancerName -&gt; (string) The name of the load balancer to associate with the Amazon ECS service or task set. If you are using an Application Load Balancer or a Network Load Balancer the load balancer name parameter should be omitted. containerName -&gt; (string) The name of the container (as it appears in a container defi- nition) to associate with the load balancer. You need to specify the container name when configuring the target group for an Amazon ECS load balancer. containerPort -&gt; (integer) The port on the container to associate with the load bal- ancer. This port must correspond to a containerPort in the task definition the tasks in the service are using. For tasks that use the EC2 launch type, the container instance they're launched on must allow ingress traffic on the hostPort of the port mapping. advancedConfiguration -&gt; (structure) The advanced settings for the load balancer used in blue/green deployments. Specify the alternate target group, listener rules, and IAM role required for traffic shifting during blue/green deployments. alternateTargetGroupArn -&gt; (string) The Amazon Resource Name (ARN) of the alternate target group for Amazon ECS blue/green deployments. productionListenerRule -&gt; (string) The Amazon Resource Name (ARN) that that identifies the production listener rule (in the case of an Application Load Balancer) or listener (in the case for an Network Load Balancer) for routing production traffic. testListenerRule -&gt; (string) The Amazon Resource Name (ARN) that identifies ) that identifies the test listener rule (in the case of an Ap- plication Load Balancer) or listener (in the case for an Network Load Balancer) for routing test traffic. roleArn -&gt; (string) The Amazon Resource Name (ARN) of the IAM role that grants Amazon ECS permission to call the Elastic Load Balancing APIs for you. Shorthand Syntax: targetGroupArn=string,loadBalancerName=string,containerName=string,containerPort=integer,advancedConfiguration={alternateTargetGroupArn=string,productionListenerRule=string,testListenerRule=string,roleArn=string} ... JSON Syntax: [ { "targetGroupArn": "string", "loadBalancerName": "string", "containerName": "string", "containerPort": integer, "advancedConfiguration": { "alternateTargetGroupArn": "string", "productionListenerRule": "string", "testListenerRule": "string", "roleArn": "string" } } ... ]
    /// </summary>
    [CliOption("--load-balancers", GroupValues = true)]
    public IEnumerable<string>? LoadBalancers { get; set; }

    /// <summary>
    /// Determines whether to propagate the tags from the task definition or the service to the task. If no value is specified, the tags aren't propagated. Only tasks launched after the update will reflect the update. To up- date the tags on all tasks, set forceNewDeployment to true , so that Amazon ECS starts new tasks with the updated tags. This parameter doesn't trigger a new service deployment. Possible values: o TASK_DEFINITION o SERVICE o NONE
    /// </summary>
    [CliOption("--propagate-tags")]
    public AwsEcsUpdateServicePropagateTags? PropagateTags { get; set; }

    /// <summary>
    /// NOTE: You must have a service-linked role when you update this prop- erty. For more information about the role see the CreateService re- quest parameter ` role https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_CreateService.html#ECS-CreateService-request-role`__ . The details for the service discovery registries to assign to this service. For more information, see Service Discovery . When you add, update, or remove the service registries configura- tion, Amazon ECS starts new tasks with the updated service reg- istries configuration, and then stops the old tasks when the new tasks are running. You can remove existing serviceRegistries by passing an empty list. This parameter triggers a new service deployment. (structure) The details for the service registry. Each service may be associated with one service registry. Multi- ple service registries for each service are not supported. When you add, update, or remove the service registries configu- ration, Amazon ECS starts a new deployment. New tasks are regis- tered and deregistered to the updated service registry configu- ration. registryArn -&gt; (string) The Amazon Resource Name (ARN) of the service registry. The currently supported service registry is Cloud Map. For more information, see CreateService . port -&gt; (integer) The port value used if your service discovery service speci- fied an SRV record. This field might be used if both the awsvpc network mode and SRV records are used. containerName -&gt; (string) The container name value to be used for your service discov- ery service. It's already specified in the task definition. If the task definition that your service task specifies uses the bridge or host network mode, you must specify a contain- erName and containerPort combination from the task defini- tion. If the task definition that your service task specifies uses the awsvpc network mode and a type SRV DNS record is used, you must specify either a containerName and container- Port combination or a port value. However, you can't specify both. containerPort -&gt; (integer) The port value to be used for your service discovery service. It's already specified in the task definition. If the task definition your service task specifies uses the bridge or host network mode, you must specify a containerName and con- tainerPort combination from the task definition. If the task definition your service task specifies uses the awsvpc net- work mode and a type SRV DNS record is used, you must specify either a containerName and containerPort combination or a port value. However, you can't specify both. Shorthand Syntax: registryArn=string,port=integer,containerName=string,containerPort=integer ... JSON Syntax: [ { "registryArn": "string", "port": integer, "containerName": "string", "containerPort": integer } ... ]
    /// </summary>
    [CliOption("--service-registries", GroupValues = true)]
    public IEnumerable<string>? ServiceRegistries { get; set; }

    /// <summary>
    /// The configuration for this service to discover and connect to ser- vices, and be discovered by, and connected from, other services within a namespace. Tasks that run in a namespace can use short names to connect to ser- vices in the namespace. Tasks can connect to services across all of the clusters in the namespace. Tasks connect through a managed proxy container that collects logs and metrics for increased visibility. Only the tasks that Amazon ECS services create are supported with Service Connect. For more information, see Service Connect in the Amazon Elastic Container Service Developer Guide . This parameter triggers a new service deployment. enabled -&gt; (boolean) [required] Specifies whether to use Service Connect with this service. namespace -&gt; (string) The namespace name or full Amazon Resource Name (ARN) of the Cloud Map namespace for use with Service Connect. The namespace must be in the same Amazon Web Services Region as the Amazon ECS service and cluster. The type of namespace doesn't affect Ser- vice Connect. For more information about Cloud Map, see Working with Services in the Cloud Map Developer Guide . services -&gt; (list) The list of Service Connect service objects. These are names and aliases (also known as endpoints) that are used by other Amazon ECS services to connect to this service. This field is not required for a "client" Amazon ECS service that's a member of a namespace only to connect to other services within the namespace. An example of this would be a frontend ap- plication that accepts incoming requests from either a load bal- ancer that's attached to the service or by other means. An object selects a port from the task definition, assigns a name for the Cloud Map service, and a list of aliases (end- points) and ports for client applications to refer to this ser- vice. (structure) The Service Connect service object configuration. For more information, see Service Connect in the Amazon Elastic Con- tainer Service Developer Guide . portName -&gt; (string) [required] The portName must match the name of one of the portMap- pings from all the containers in the task definition of this Amazon ECS service. discoveryName -&gt; (string) The discoveryName is the name of the new Cloud Map ser- vice that Amazon ECS creates for this Amazon ECS service. This must be unique within the Cloud Map namespace. The name can contain up to 64 characters. The name can in- clude lowercase letters, numbers, underscores (_), and hyphens (-). The name can't start with a hyphen. If the discoveryName isn't specified, the port mapping name from the task definition is used in portName.name- space . clientAliases -&gt; (list) The list of client aliases for this Service Connect ser- vice. You use these to assign names that can be used by client applications. The maximum number of client aliases that you can have in this list is 1. Each alias ("endpoint") is a fully-qualified name and port number that other Amazon ECS tasks ("clients") can use to connect to this service. Each name and port mapping must be unique within the namespace. For each ServiceConnectService , you must provide at least one clientAlias with one port . (structure) Each alias ("endpoint") is a fully-qualified name and port number that other tasks ("clients") can use to connect to this service. Each name and port mapping must be unique within the namespace. Tasks that run in a namespace can use short names to connect to services in the namespace. Tasks can con- nect to services across all of the clusters in the namespace. Tasks connect through a managed proxy con- tainer that collects logs and metrics for increased visibility. Only the tasks that Amazon ECS services create are supported with Service Connect. For more information, see Service Connect in the Amazon Elastic Container Service Developer Guide . port -&gt; (integer) [required] The listening port number for the Service Connect proxy. This port is available inside of all of the tasks within the same namespace. To avoid changing your applications in client Ama- zon ECS services, set this to the same port that the client application uses by default. For more information, see Service Connect in the Amazon Elastic Container Service Developer Guide . Constraints: o min: 0 o max: 65535 dnsName -&gt; (string) The dnsName is the name that you use in the appli- cations of client tasks to connect to this ser- vice. The name must be a valid DNS name but doesn't need to be fully-qualified. The name can include up to 127 characters. The name can include lowercase letters, numbers, underscores (_), hy- phens (-), and periods (.). The name can't start with a hyphen. If this parameter isn't specified, the default value of discoveryName.namespace is used. If the discoveryName isn't specified, the port mapping name from the task definition is used in port- Name.namespace . To avoid changing your applications in client Ama- zon ECS services, set this to the same name that the client application uses by default. For exam- ple, a few common names are database , db , or the lowercase name of a database, such as mysql or re- dis . For more information, see Service Connect in the Amazon Elastic Container Service Developer Guide . testTrafficRules -&gt; (structure) The configuration for test traffic routing rules used during blue/green deployments with Amazon ECS Service Connect. This allows you to route a por- tion of traffic to the new service revision of your service for testing before shifting all pro- duction traffic. header -&gt; (structure) [required] The HTTP header-based routing rules that deter- mine which requests should be routed to the new service version during blue/green deployment testing. These rules provide fine-grained con- trol over test traffic routing based on request headers. name -&gt; (string) [required] The name of the HTTP header to examine for test traffic routing. Common examples in- clude custom headers like X-Test-Version or X-Canary-Request that can be used to iden- tify test traffic. value -&gt; (structure) The header value matching configuration that determines how the HTTP header value is evaluated for test traffic routing deci- sions. exact -&gt; (string) [required] The exact value that the HTTP header must match for the test traffic routing rule to apply. This provides precise control over which requests are routed to the new service revision during blue/green deployments. ingressPortOverride -&gt; (integer) The port number for the Service Connect proxy to listen on. Use the value of this field to bypass the proxy for traf- fic on the port number specified in the named portMapping in the task definition of this application, and then use it in your VPC security groups to allow traffic into the proxy for this Amazon ECS service. In awsvpc mode and Fargate, the default value is the con- tainer port number. The container port number is in the portMapping in the task definition. In bridge mode, the default value is the ephemeral port of the Service Con- nect proxy. Constraints: o min: 0 o max: 65535 timeout -&gt; (structure) A reference to an object that represents the configured timeouts for Service Connect. idleTimeoutSeconds -&gt; (integer) The amount of time in seconds a connection will stay active while idle. A value of 0 can be set to disable idleTimeout . The idleTimeout default for HTTP /HTTP2 /GRPC is 5 minutes. The idleTimeout default for TCP is 1 hour. Constraints: o min: 0 o max: 2147483647 perRequestTimeoutSeconds -&gt; (integer) The amount of time waiting for the upstream to respond with a complete response per request. A value of 0 can be set to disable perRequestTimeout . perRequestTime- out can only be set if Service Connect appProtocol isn't TCP . Only idleTimeout is allowed for TCP app- Protocol . Constraints: o min: 0 o max: 2147483647 tls -&gt; (structure) A reference to an object that represents a Transport Layer Security (TLS) configuration. issuerCertificateAuthority -&gt; (structure) [required] The signer certificate authority. awsPcaAuthorityArn -&gt; (string) The ARN of the Amazon Web Services Private Cer- tificate Authority certificate. kmsKey -&gt; (string) The Amazon Web Services Key Management Service key. roleArn -&gt; (string) The Amazon Resource Name (ARN) of the IAM role that's associated with the Service Connect TLS. logConfiguration -&gt; (structure) The log configuration for the container. This parameter maps to LogConfig in the docker container create command and the --log-driver option to docker run. By default, containers use the same logging driver that the Docker daemon uses. However, the container might use a different logging driver than the Docker daemon by specifying a log driver configuration in the container definition. Understand the following when specifying a log configuration for your containers. o Amazon ECS currently supports a subset of the logging drivers available to the Docker daemon. Additional log drivers may be available in future releases of the Amazon ECS container agent. For tasks on Fargate, the supported log drivers are awslogs , splunk , and awsfirelens . For tasks hosted on Ama- zon EC2 instances, the supported log drivers are awslogs , fluentd , gelf , json-file , journald ,``syslog`` , splunk , and awsfirelens . o This parameter requires version 1.18 of the Docker Remote API or greater on your container instance. o For tasks that are hosted on Amazon EC2 instances, the Amazon ECS container agent must register the available logging dri- vers with the ECS_AVAILABLE_LOGGING_DRIVERS environment vari- able before containers placed on that instance can use these log configuration options. For more information, see Amazon ECS container agent configuration in the Amazon Elastic Con- tainer Service Developer Guide . o For tasks that are on Fargate, because you don't have access to the underlying infrastructure your tasks are hosted on, any additional software needed must be installed outside of the task. For example, the Fluentd output aggregators or a remote host running Logstash to send Gelf logs to. logDriver -&gt; (string) [required] The log driver to use for the container. For tasks on Fargate, the supported log drivers are awslogs , splunk , and awsfirelens . For tasks hosted on Amazon EC2 instances, the supported log drivers are awslogs , fluentd , gelf , json-file , journald , syslog , splunk , and awsfirelens . For more information about using the awslogs log driver, see Send Amazon ECS logs to CloudWatch in the Amazon Elastic Con- tainer Service Developer Guide . For more information about using the awsfirelens log driver, see Send Amazon ECS logs to an Amazon Web Services service or Amazon Web Services Partner . NOTE: If you have a custom driver that isn't listed, you can fork the Amazon ECS container agent project that's available on GitHub and customize it to work with that driver. We encourage you to submit pull requests for changes that you would like to have included. However, we don't currently provide support for running modified copies of this software. Possible values: o json-file o syslog o journald o gelf o fluentd o awslogs o splunk o awsfirelens options -&gt; (map) The configuration options to send to the log driver. The options you can specify depend on the log driver. Some of the options you can specify when you use the awslogs log dri- ver to route logs to Amazon CloudWatch include the following: awslogs-create-group Required: No Specify whether you want the log group to be created automat- ically. If this option isn't specified, it defaults to false . NOTE: Your IAM policy must include the logs:CreateLogGroup per- mission before you attempt to use awslogs-create-group . awslogs-region Required: Yes Specify the Amazon Web Services Region that the awslogs log driver is to send your Docker logs to. You can choose to send all of your logs from clusters in different Regions to a sin- gle region in CloudWatch Logs. This is so that they're all visible in one location. Otherwise, you can separate them by Region for more granularity. Make sure that the specified log group exists in the Region that you specify with this option. awslogs-group Required: Yes Make sure to specify a log group that the awslogs log driver sends its log streams to. awslogs-stream-prefix Required: Yes, when using Fargate.Optional when using EC2. Use the awslogs-stream-prefix option to associate a log stream with the specified prefix, the container name, and the ID of the Amazon ECS task that the container belongs to. If you specify a prefix with this option, then the log stream takes the format prefix-name/container-name/ecs-task-id . If you don't specify a prefix with this option, then the log stream is named after the container ID that's assigned by the Docker daemon on the container instance. Because it's diffi- cult to trace logs back to the container that sent them with just the Docker container ID (which is only available on the container instance), we recommend that you specify a prefix with this option. For Amazon ECS services, you can use the service name as the prefix. Doing so, you can trace log streams to the service that the container belongs to, the name of the container that sent them, and the ID of the task that the container belongs to. You must specify a stream-prefix for your logs to have your logs appear in the Log pane when using the Amazon ECS con- sole. awslogs-datetime-format Required: No This option defines a multiline start pattern in Python strf- time format. A log message consists of a line that matches the pattern and any following lines that dont match the pat- tern. The matched line is the delimiter between log messages. One example of a use case for using this format is for pars- ing output such as a stack dump, which might otherwise be logged in multiple entries. The correct pattern allows it to be captured in a single entry. For more information, see awslogs-datetime-format . You cannot configure both the awslogs-datetime-format and awslogs-multiline-pattern options. NOTE: Multiline logging performs regular expression parsing and matching of all log messages. This might have a negative impact on logging performance. awslogs-multiline-pattern Required: No This option defines a multiline start pattern that uses a regular expression. A log message consists of a line that matches the pattern and any following lines that dont match the pattern. The matched line is the delimiter between log messages. For more information, see awslogs-multiline-pattern . This option is ignored if awslogs-datetime-format is also configured. You cannot configure both the awslogs-datetime-format and awslogs-multiline-pattern options. NOTE: Multiline logging performs regular expression parsing and matching of all log messages. This might have a negative impact on logging performance. The following options apply to all supported log drivers. mode Required: No Valid values: non-blocking | blocking This option defines the delivery mode of log messages from the container to the log driver specified using logDriver . The delivery mode you choose affects application availability when the flow of logs from container is interrupted. If you use the blocking mode and the flow of logs is inter- rupted, calls from container code to write to the stdout and stderr streams will block. The logging thread of the applica- tion will block as a result. This may cause the application to become unresponsive and lead to container healthcheck failure. If you use the non-blocking mode, the container's logs are instead stored in an in-memory intermediate buffer configured with the max-buffer-size option. This prevents the applica- tion from becoming unresponsive when logs cannot be sent. We recommend using this mode if you want to ensure service availability and are okay with some log loss. For more infor- mation, see Preventing log loss with non-blocking mode in the ``awslogs` container log driver &lt;- http://aws.amazon.com/blogs/containers/prevent- ing-log-loss-with-non-blocking-mode-in-the-awslogs-con- tainer-log-driver/&gt;`__ . You can set a default mode for all containers in a specific Amazon Web Services Region by using the defaultLogDriverMode account setting. If you don't specify the mode option or con- figure the account setting, Amazon ECS will default to the non-blocking mode. For more information about the account setting, see Default log driver mode in the Amazon Elastic Container Service Developer Guide . NOTE: On June 25, 2025, Amazon ECS changed the default log dri- ver mode from blocking to non-blocking to prioritize task availability over logging. To continue using the blocking mode after this change, do one of the following: o Set the mode option in your container definition's log- Configuration as blocking . o Set the defaultLogDriverMode account setting to block- ing . max-buffer-size Required: No Default value: 10m When non-blocking mode is used, the max-buffer-size log op- tion controls the size of the buffer that's used for interme- diate message storage. Make sure to specify an adequate buffer size based on your application. When the buffer fills up, further logs cannot be stored. Logs that cannot be stored are lost. To route logs using the splunk log router, you need to spec- ify a splunk-token and a splunk-url . When you use the awsfirelens log router to route logs to an Amazon Web Services Service or Amazon Web Services Partner Network destination for log storage and analytics, you can set the log-driver-buffer-limit option to limit the number of events that are buffered in memory, before being sent to the log router container. It can help to resolve potential log loss issue because high throughput might result in memory running out for the buffer inside of Docker. Other options you can specify when using awsfirelens to route logs depend on the destination. When you export logs to Ama- zon Data Firehose, you can specify the Amazon Web Services Region with region and a name for the log stream with deliv- ery_stream . When you export logs to Amazon Kinesis Data Streams, you can specify an Amazon Web Services Region with region and a data stream name with stream . When you export logs to Amazon OpenSearch Service, you can specify options like Name , Host (OpenSearch Service endpoint without protocol), Port , Index , Type , Aws_auth , Aws_re- gion , Suppress_Type_Name , and tls . For more information, see Under the hood: FireLens for Amazon ECS Tasks . When you export logs to Amazon S3, you can specify the bucket using the bucket option. You can also specify region , to- tal_file_size , upload_timeout , and use_put_object as op- tions. This parameter requires version 1.19 of the Docker Remote API or greater on your container instance. To check the Docker Remote API version on your container instance, log in to your container instance and run the following command: sudo docker version --format '{{.Server.APIVersion}}' key -&gt; (string) value -&gt; (string) secretOptions -&gt; (list) The secrets to pass to the log configuration. For more infor- mation, see Specifying sensitive data in the Amazon Elastic Container Service Developer Guide . (structure) An object representing the secret to expose to your con- tainer. Secrets can be exposed to a container in the fol- lowing ways: o To inject sensitive data into your containers as envi- ronment variables, use the secrets container definition parameter. o To reference sensitive information in the log configu- ration of a container, use the secretOptions container definition parameter. For more information, see Specifying sensitive data in the Amazon Elastic Container Service Developer Guide . name -&gt; (string) [required] The name of the secret. valueFrom -&gt; (string) [required] The secret to expose to the container. The supported values are either the full ARN of the Secrets Manager secret or the full ARN of the parameter in the SSM Pa- rameter Store. For information about the require Identity and Access Management permissions, see Required IAM permissions for Amazon ECS secrets (for Secrets Manager) or Required IAM permissions for Amazon ECS secrets (for Systems Manager Parameter store) in the Amazon Elastic Container Service Developer Guide . NOTE: If the SSM Parameter Store parameter exists in the same Region as the task you're launching, then you can use either the full ARN or name of the parame- ter. If the parameter exists in a different Re- gion, then the full ARN must be specified. accessLogConfiguration -&gt; (structure) The configuration for Service Connect access logging. Access logs capture detailed information about requests made to your service, including request patterns, response codes, and timing data. They can be useful for debugging connectivity issues, mon- itoring service performance, and auditing service-to-service communication for security and compliance purposes. NOTE: To enable access logs, you must also specify a logConfigura- tion in the serviceConnectConfiguration . format -&gt; (string) [required] The format for Service Connect access log output. Choose TEXT for human-readable logs or JSON for structured data that in- tegrates well with log analysis tools. Possible values: o TEXT o JSON includeQueryParameters -&gt; (string) Specifies whether to include query parameters in Service Con- nect access logs. When enabled, query parameters from HTTP requests are in- cluded in the access logs. Consider security and privacy im- plications when enabling this feature, as query parameters may contain sensitive information such as request IDs and to- kens. By default, this parameter is DISABLED . Possible values: o DISABLED o ENABLED JSON Syntax: { "enabled": true|false, "namespace": "string", "services": [ { "portName": "string", "discoveryName": "string", "clientAliases": [ { "port": integer, "dnsName": "string", "testTrafficRules": { "header": { "name": "string", "value": { "exact": "string" } } } } ... ], "ingressPortOverride": integer, "timeout": { "idleTimeoutSeconds": integer, "perRequestTimeoutSeconds": integer }, "tls": { "issuerCertificateAuthority": { "awsPcaAuthorityArn": "string" }, "kmsKey": "string", "roleArn": "string" } } ... ], "logConfiguration": { "logDriver": "json-file"|"syslog"|"journald"|"gelf"|"fluentd"|"awslogs"|"splunk"|"awsfirelens", "options": {"string": "string" ...}, "secretOptions": [ { "name": "string", "valueFrom": "string" } ... ] }, "accessLogConfiguration": { "format": "TEXT"|"JSON", "includeQueryParameters": "DISABLED"|"ENABLED" } }
    /// </summary>
    [CliOption("--service-connect-configuration")]
    public string? ServiceConnectConfiguration { get; set; }

    /// <summary>
    /// The details of the volume that was configuredAtLaunch . You can con- figure the size, volumeType, IOPS, throughput, snapshot and encryp- tion in ServiceManagedEBSVolumeConfiguration . The name of the vol- ume must match the name from the task definition. If set to null, no new deployment is triggered. Otherwise, if this configuration dif- fers from the existing one, it triggers a new deployment. This parameter triggers a new service deployment. (structure) The configuration for a volume specified in the task definition as a volume that is configured at launch time. Currently, the only supported volume type is an Amazon EBS volume. name -&gt; (string) [required] The name of the volume. This value must match the volume name from the Volume object in the task definition. managedEBSVolume -&gt; (structure) The configuration for the Amazon EBS volume that Amazon ECS creates and manages on your behalf. These settings are used to create each Amazon EBS volume, with one volume created for each task in the service. The Amazon EBS volumes are visible in your account in the Amazon EC2 console once they are cre- ated. encrypted -&gt; (boolean) Indicates whether the volume should be encrypted. If you turn on Region-level Amazon EBS encryption by default but set this value as false , the setting is overridden and the volume is encrypted with the KMS key specified for Amazon EBS encryption by default. This parameter maps 1:1 with the Encrypted parameter of the CreateVolume API in the Amazon EC2 API Reference . kmsKeyId -&gt; (string) The Amazon Resource Name (ARN) identifier of the Amazon Web Services Key Management Service key to use for Amazon EBS encryption. When a key is specified using this para- meter, it overrides Amazon EBS default encryption or any KMS key that you specified for cluster-level managed storage encryption. This parameter maps 1:1 with the KmsKeyId parameter of the CreateVolume API in the Amazon EC2 API Reference . For more information about encrypting Amazon EBS volumes attached to tasks, see Encrypt data stored in Amazon EBS volumes attached to Amazon ECS tasks . WARNING: Amazon Web Services authenticates the Amazon Web Ser- vices Key Management Service key asynchronously. Therefore, if you specify an ID, alias, or ARN that is invalid, the action can appear to complete, but even- tually fails. volumeType -&gt; (string) The volume type. This parameter maps 1:1 with the Volume- Type parameter of the CreateVolume API in the Amazon EC2 API Reference . For more information, see Amazon EBS vol- ume types in the Amazon EC2 User Guide . The following are the supported volume types. o General Purpose SSD: gp2 | gp3 System Message: WARNING/2 (&lt;string&gt;:, line 3039) Inline substitution_reference start-string without end-string. o Provisioned IOPS SSD: io1 | io2 System Message: WARNING/2 (&lt;string&gt;:, line 3041) Inline substitution_reference start-string without end-string. o Throughput Optimized HDD: st1 o Cold HDD: sc1 o Magnetic: standard NOTE: The magnetic volume type is not supported on Fargate. sizeInGiB -&gt; (integer) The size of the volume in GiB. You must specify either a volume size or a snapshot ID. If you specify a snapshot ID, the snapshot size is used for the volume size by de- fault. You can optionally specify a volume size greater than or equal to the snapshot size. This parameter maps 1:1 with the Size parameter of the CreateVolume API in the Amazon EC2 API Reference . The following are the supported volume size values for each volume type. o gp2 and gp3 : 1-16,384 o io1 and io2 : 4-16,384 o st1 and sc1 : 125-16,384 o standard : 1-1,024 snapshotId -&gt; (string) The snapshot that Amazon ECS uses to create volumes for attachment to tasks maintained by the service. You must specify either snapshotId or sizeInGiB in your volume configuration. This parameter maps 1:1 with the Snap- shotId parameter of the CreateVolume API in the Amazon EC2 API Reference . volumeInitializationRate -&gt; (integer) The rate, in MiB/s, at which data is fetched from a snap- shot of an existing EBS volume to create new volumes for attachment to the tasks maintained by the service. This property can be specified only if you specify a snap- shotId . For more information, see Initialize Amazon EBS volumes in the Amazon EBS User Guide . iops -&gt; (integer) The number of I/O operations per second (IOPS). For gp3 , io1 , and io2 volumes, this represents the number of IOPS that are provisioned for the volume. For gp2 volumes, this represents the baseline performance of the volume and the rate at which the volume accumulates I/O credits for bursting. The following are the supported values for each volume type. o gp3 : 3,000 - 16,000 IOPS o io1 : 100 - 64,000 IOPS o io2 : 100 - 256,000 IOPS This parameter is required for io1 and io2 volume types. The default for gp3 volumes is 3,000 IOPS . This parame- ter is not supported for st1 , sc1 , or standard volume types. This parameter maps 1:1 with the Iops parameter of the CreateVolume API in the Amazon EC2 API Reference . throughput -&gt; (integer) The throughput to provision for a volume, in MiB/s, with a maximum of 1,000 MiB/s. This parameter maps 1:1 with the Throughput parameter of the CreateVolume API in the Amazon EC2 API Reference . WARNING: This parameter is only supported for the gp3 volume type. tagSpecifications -&gt; (list) The tags to apply to the volume. Amazon ECS applies ser- vice-managed tags by default. This parameter maps 1:1 with the TagSpecifications.N parameter of the CreateVolume API in the Amazon EC2 API Reference . (structure) The tag specifications of an Amazon EBS volume. resourceType -&gt; (string) [required] The type of volume resource. Possible values: o volume tags -&gt; (list) The tags applied to this Amazon EBS volume. Ama- zonECSCreated and AmazonECSManaged are reserved tags that can't be used. Constraints: o min: 0 o max: 50 (structure) The metadata that you apply to a resource to help you categorize and organize them. Each tag consists of a key and an optional value. You define them. The following basic restrictions apply to tags: o Maximum number of tags per resource - 50 o For each resource, each tag key must be unique, and each tag key can have only one value. o Maximum key length - 128 Unicode characters in UTF-8 o Maximum value length - 256 Unicode characters in UTF-8 o If your tagging schema is used across multi- ple services and resources, remember that other services may have restrictions on al- lowed characters. Generally allowed charac- ters are: letters, numbers, and spaces repre- sentable in UTF-8, and the following charac- ters: + - = . _ : / @. o Tag keys and values are case-sensitive. o Do not use aws: , AWS: , or any upper or low- ercase combination of such as a prefix for either keys or values as it is reserved for Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with this prefix do not count against your tags per resource limit. key -&gt; (string) One part of a key-value pair that make up a tag. A key is a general label that acts like a category for more specific tag val- ues. Constraints: o min: 1 o max: 128 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) value -&gt; (string) The optional part of a key-value pair that make up a tag. A value acts as a descriptor within a tag category (key). Constraints: o min: 0 o max: 256 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) propagateTags -&gt; (string) Determines whether to propagate the tags from the task definition to the Amazon EBS volume. Tags can only propagate to a SERVICE specified in Ser- viceVolumeConfiguration . If no value is speci- fied, the tags aren't propagated. Possible values: o TASK_DEFINITION o SERVICE o NONE roleArn -&gt; (string) [required] The ARN of the IAM role to associate with this volume. This is the Amazon ECS infrastructure IAM role that is used to manage your Amazon Web Services infrastructure. We recommend using the Amazon ECS-managed AmazonECSInfra- structureRolePolicyForVolumes IAM policy with this role. For more information, see Amazon ECS infrastructure IAM role in the Amazon ECS Developer Guide . filesystemType -&gt; (string) The filesystem type for the volume. For volumes created from a snapshot, you must specify the same filesystem type that the volume was using when the snapshot was cre- ated. If there is a filesystem type mismatch, the tasks will fail to start. The available Linux filesystem types are ext3 , ext4 , and xfs . If no value is specified, the xfs filesystem type is used by default. The available Windows filesystem types are NTFS . Possible values: o ext3 o ext4 o xfs o ntfs JSON Syntax: [ { "name": "string", "managedEBSVolume": { "encrypted": true|false, "kmsKeyId": "string", "volumeType": "string", "sizeInGiB": integer, "snapshotId": "string", "volumeInitializationRate": integer, "iops": integer, "throughput": integer, "tagSpecifications": [ { "resourceType": "volume", "tags": [ { "key": "string", "value": "string" } ... ], "propagateTags": "TASK_DEFINITION"|"SERVICE"|"NONE" } ... ], "roleArn": "string", "filesystemType": "ext3"|"ext4"|"xfs"|"ntfs" } } ... ]
    /// </summary>
    [CliOption("--volume-configurations", GroupValues = true)]
    public IEnumerable<string>? VolumeConfigurations { get; set; }

    /// <summary>
    /// An object representing the VPC Lattice configuration for the service being updated. This parameter triggers a new service deployment. (structure) The VPC Lattice configuration for your service that holds the information for the target group(s) Amazon ECS tasks will be registered to. roleArn -&gt; (string) [required] The ARN of the IAM role to associate with this VPC Lattice configuration. This is the Amazon ECS infrastructure IAM role that is used to manage your VPC Lattice infrastructure. targetGroupArn -&gt; (string) [required] The full Amazon Resource Name (ARN) of the target group or groups associated with the VPC Lattice configuration that the Amazon ECS tasks will be registered to. portName -&gt; (string) [required] The name of the port mapping to register in the VPC Lattice target group. This is the name of the portMapping you defined in your task definition. Shorthand Syntax: roleArn=string,targetGroupArn=string,portName=string ... JSON Syntax: [ { "roleArn": "string", "targetGroupArn": "string", "portName": "string" } ... ]
    /// </summary>
    [CliOption("--vpc-lattice-configurations", GroupValues = true)]
    public IEnumerable<string>? VpcLatticeConfigurations { get; set; }

    /// <summary>
    /// The optional monitoring configuration for the service, which defines the resolution for the service-level CPUUtilization and MemoryUti- lization Amazon CloudWatch metrics. When not specified, Amazon ECS uses the default resolution of 60 seconds. metricConfigurations -&gt; (list) The list of metric configurations for the service monitoring. Constraints: o min: 0 o max: 5 (structure) The configuration for a specific set of metrics to collect for a service. metricNames -&gt; (list) [required] The list of metric names to configure. The supported met- ric names are CPUUtilization and MemoryUtilization . Constraints: o min: 1 o max: 5 (string) Constraints: o min: 1 o max: 255 resolutionSeconds -&gt; (integer) [required] The resolution, in seconds, at which to collect the met- rics. The valid values are 20 and 60 . Constraints: o min: 20 o max: 60 JSON Syntax: { "metricConfigurations": [ { "metricNames": ["string", ...], "resolutionSeconds": integer } ... ] }
    /// </summary>
    [CliOption("--monitoring")]
    public string? Monitoring { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

}
